function testBackground(kind = '') {
  return `<div class="design-background" aria-hidden="true">${[2,3,0,1].map(i=>`<span class="design-glow ${i>1?'upper':'lower'} ${i%2?'light':''}"><img src="${testAsset(`${kind==='course'?'course-latest':'8563'}-imgElement${i||''}`)}" alt="" /></span>`).join('')}</div>`;
}

function testVoucherScreen(kind, partial) {
  const mobile=kind==='mobile',amount=payableAmount();
  const balance=partial?Math.min(4000,amount):mobile?20000:amount;
  const remaining=Math.max(0,amount-balance);
  const title=mobile?'모바일 상품권을 사용하시겠습니까?':'할인 쿠폰을 사용하시겠습니까?';
  const content=`<div class="test-voucher-amounts"><p><span>결제 금액</span><strong>${formatPrice(amount)}</strong></p><p><span>상품권 금액</span><strong>${formatPrice(balance)}</strong></p><p class="test-voucher-total ${remaining?'has-balance':''}"><img src="${testAsset('voucher-divider')}" alt="" /><span>추가 결제</span><strong>${remaining?formatPrice(remaining):'없음'}</strong></p></div>`;
  const dialog=testDialog({title,content,className:'test-voucher-dialog',node:mobile?partial?'543:8696':'543:8681':partial?'543:8699':'543:8693',actions:[{label:partial?'잔액 추가결제':'사용',action:mobile?partial?'voucher-partial':'voucher-complete':partial?'paper-partial':'paper-complete'}],secondary:{label:'사용 안함',action:mobile?'voucher-cancel':'paper-cancel'}});
  return scanScreen(kind,mobile?'voucher-use':'paper-use',mobile?'상품권 사용':'할인 쿠폰 사용',dialog);
}

